Rules.InvariantScript:
Concurrent(
    ClearCollect(
        colNotStarted,
        Filter(
            'Issue tracker',
            Status.Value = "New",
            'Created By'.Email = User().Email
        )
    ),
    ClearCollect(
        colInProgress,
        Filter(
            'Issue tracker',
            Status.Value = "In Progress",
            'Created By'.Email = User().Email
        )
    ),
    ClearCollect(
        colComplete,
        Filter(
            'Issue tracker',
            Status.Value = "Completed",
            'Created By'.Email = User().Email
        )
    ),
    ClearCollect(
        colBlocked,
        Filter(
            'Issue tracker',
            Status.Value = "Blocked",
            'Created By'.Email = User().Email
        )
    )
);
ClearCollect(
    colIssueCounts,
    {
        Title: "Not Started",
        Status: "New",
        Count: CountRows(colNotStarted),
        Icon: Icon.CancelBadge
    },
    {
        Title: "In Progress",
        Status: "In Progress",
        Count: CountRows(colInProgress),
        Icon: Icon.HalfFilledCircle
    },
    {
        Title: "Completed",
        Status: "Completed",
        Count: CountRows(colComplete),
        Icon: Icon.CheckBadge
    },
    {
        Title: "Blocked",
        Status: "Blocked",
        Count: CountRows(colBlocked),
        Icon: Icon.Blocked
    }
)
